// Des: Per-job state files: once marks, last fire, chain stats
// Flo: id check > state dir > read or write small file
// I/O: job id + stamp or stats > state file on disk
// ===================================================================
const std = @import("std"); const builtin = @import("builtin"); const stor = @import("store");
const tkstorbase = @import("tk-stor-base.zig"); const CF = tkstorbase.CF; const CMDS_SCRI = tkstorbase.CMDS_SCRI; const ChaiStat = tkstorbase.ChaiStat; const DEFA_TMOZ_SECO = tkstorbase.DEFA_TMOZ_SECO; const Load = tkstorbase.Load; const MAXZ_CWDZ = tkstorbase.MAXZ_CWDZ; const MAXZ_FILE = tkstorbase.MAXZ_FILE; const MAXZ_IDSZ = tkstorbase.MAXZ_IDSZ; const MAXZ_LOCK = tkstorbase.MAXZ_LOCK; const MAXZ_PLUS_POOL = tkstorbase.MAXZ_PLUS_POOL; const MAXZ_RETR = tkstorbase.MAXZ_RETR; const MAXZ_RUNZ = tkstorbase.MAXZ_RUNZ; const MAXZ_TMOZ_SECO = tkstorbase.MAXZ_TMOZ_SECO; const NONE_SCHE = tkstorbase.NONE_SCHE; const PLUS_BIGZ = tkstorbase.PLUS_BIGZ; const PLUS_MAXZ = tkstorbase.PLUS_MAXZ; const Reje = tkstorbase.Reje; const STAT_DIRZ = tkstorbase.STAT_DIRZ; const TYPE_LIST = tkstorbase.TYPE_LIST; const Task = tkstorbase.Task; const WINZ_ONLY = tkstorbase.WINZ_ONLY; const autoIdenChec = tkstorbase.autoIdenChec; const chaiChec = tkstorbase.chaiChec; const idenVali = tkstorbase.idenVali; const norm = tkstorbase.norm; const scheNeed = tkstorbase.scheNeed; const taskPath = tkstorbase.taskPath; const typeChec = tkstorbase.typeChec; const winzOnlyChec = tkstorbase.winzOnlyChec;
pub fn statDirz(allo: std.mem.Allocator, iozz: std.Io) ![]const u8 { const home = std.process.Environ.getAlloc(stor.enviLive(), allo, stor.HOME_VARZ) catch return error.NoHomeDir; const dirz = try std.fs.path.join(allo, &.{ home, stor.tune.data, STAT_DIRZ }); std.Io.Dir.cwd().createDirPath(iozz, dirz) catch {}; return dirz; }
fn statPath(allo: std.mem.Allocator, iozz: std.Io, iden: []const u8) ![]const u8 { const dirz = try statDirz(allo, iozz); return std.fmt.allocPrint(allo, "{s}{c}{s}.done", .{ dirz, std.fs.path.sep, iden }); }
pub fn onceFireMark(allo: std.mem.Allocator, iozz: std.Io, iden: []const u8, stam: []const u8) void { if (idenVali(iden) != null) return; const path = statPath(allo, iozz, iden) catch return; var file = std.Io.Dir.cwd().createFile(iozz, path, .{ .truncate = true }) catch return; defer file.close(iozz); file.writePositionalAll(iozz, stam, 0) catch {}; }
pub fn fireLastWrit(allo: std.mem.Allocator, iozz: std.Io, iden: []const u8, minu_stam: i64) void { if (idenVali(iden) != null) return; const dirz = statDirz(allo, iozz) catch return; const path = std.fmt.allocPrint(allo, "{s}{c}{s}.last", .{ dirz, std.fs.path.sep, iden }) catch return; var buff: [24]u8 = undefined; const text = std.fmt.bufPrint(&buff, "{d}", .{minu_stam}) catch return; var file = std.Io.Dir.cwd().createFile(iozz, path, .{ .truncate = true }) catch return; defer file.close(iozz); file.writePositionalAll(iozz, text, 0) catch {}; }
pub fn fireLastRead(allo: std.mem.Allocator, iozz: std.Io, iden: []const u8) ?i64 { if (idenVali(iden) != null) return null; const dirz = statDirz(allo, iozz) catch return null; const path = std.fmt.allocPrint(allo, "{s}{c}{s}.last", .{ dirz, std.fs.path.sep, iden }) catch return null; const data = std.Io.Dir.cwd().readFileAlloc(iozz, path, allo, .limited(64)) catch return null; return std.fmt.parseInt(i64, std.mem.trim(u8, data, " \t\r\n"), 10) catch null; }
pub fn chaiStatWrit(allo: std.mem.Allocator, iozz: std.Io, iden: []const u8, stat: ChaiStat) void { if (idenVali(iden) != null) return; const dirz = statDirz(allo, iozz) catch return; const path = std.fmt.allocPrint(allo, "{s}{c}{s}.chain", .{ dirz, std.fs.path.sep, iden }) catch return; const text = std.fmt.allocPrint(allo, "{d} {d} {d} {d} {d}\n", .{ stat.inde, stat.ranz, stat.fail, stat.next_msec, stat.star_msec }) catch return; var file = std.Io.Dir.cwd().createFile(iozz, path, .{ .truncate = true }) catch return; defer file.close(iozz); file.writePositionalAll(iozz, text, 0) catch {}; }
pub fn chaiStatRead(allo: std.mem.Allocator, iozz: std.Io, iden: []const u8) ?ChaiStat { if (idenVali(iden) != null) return null; const dirz = statDirz(allo, iozz) catch return null; const path = std.fmt.allocPrint(allo, "{s}{c}{s}.chain", .{ dirz, std.fs.path.sep, iden }) catch return null; const data = std.Io.Dir.cwd().readFileAlloc(iozz, path, allo, .limited(256)) catch return null; var iter = std.mem.tokenizeAny(u8, data, " \t\r\n"); const inde = std.fmt.parseInt(u32, iter.next() orelse return null, 10) catch return null; const ranz = std.fmt.parseInt(u32, iter.next() orelse return null, 10) catch return null; const fail = std.fmt.parseInt(u32, iter.next() orelse return null, 10) catch return null; const next_msec = std.fmt.parseInt(i64, iter.next() orelse return null, 10) catch return null; const star_msec = std.fmt.parseInt(i64, iter.next() orelse return null, 10) catch return null; return .{ .inde = inde, .ranz = ranz, .fail = fail, .next_msec = next_msec, .star_msec = star_msec }; }
pub fn chaiStatClea(allo: std.mem.Allocator, iozz: std.Io, iden: []const u8) void { if (idenVali(iden) != null) return; const dirz = statDirz(allo, iozz) catch return; const path = std.fmt.allocPrint(allo, "{s}{c}{s}.chain", .{ dirz, std.fs.path.sep, iden }) catch return; std.Io.Dir.cwd().deleteFile(iozz, path) catch {}; }
pub fn onceFireClea(allo: std.mem.Allocator, iozz: std.Io, iden: []const u8) void { if (idenVali(iden) != null) return; const path = statPath(allo, iozz, iden) catch return; std.Io.Dir.cwd().deleteFile(iozz, path) catch {}; }
pub fn onceStamRead(allo: std.mem.Allocator, iozz: std.Io, iden: []const u8) []const u8 { if (idenVali(iden) != null) return ""; const path = statPath(allo, iozz, iden) catch return ""; var file = std.Io.Dir.cwd().openFile(iozz, path, .{}) catch return ""; defer file.close(iozz); var buff: [64]u8 = undefined; var read = file.reader(iozz, &buff); const size = read.interface.readSliceShort(&buff) catch return ""; const outz = allo.dupe(u8, std.mem.trim(u8, buff[0..size], " \t\r\n")) catch return ""; return outz; }
